{"results": [{"id": "hp_doc_c9a499639c80262470a500dd982ed18685f24b7f8650d44b02ef13acb3972b28", "title": "A Bar at the Folies-Bergère", "text": "A Bar at the Folies-Bergère (French: \"Un bar aux Folies Bergère\" ), painted and exhibited at the Paris Salon in 1882, is considered the last major work of French painter Édouard Manet. It depicts a scene in the Folies Bergère nightclub in Paris. It originally belonged to the composer Emmanuel Chabrier, who was Manet's neighbor, and hung over his piano.", "score": 16.4151}, {"id": "hp_doc_862bfe2510f7c3e7a59663a46f1f0d066ebc6a27b9618cac58e37919e36e1003", "title": "The Woman from the Folies Bergères", "text": "The Woman from the Folies Bergères (German: Die Frauen von Folies Bergères) is a 1927 French-German silent film directed by Joe Francis and Max Obal and starring Claire Rommer, Carl Auen and Josephine Baker.", "score": 15.6011}, {"id": "hp_doc_e826534136b2958bd9221fa6f6ce7902f31f6dea1355752122ccf6915d535efd", "title": "Ziegfeld girl", "text": "Ziegfeld Girls were the chorus girls from Florenz Ziegfeld's theatrical Broadway revue spectaculars known as the \"Ziegfeld Follies\" (1907–1931), in New York City, which were based on the Folies Bergère of Paris.", "score": 11.3295}], "remaining_searches": 2}
